-- Seed DALI's shared Learned Intelligence Registry.
-- The live rows are already populated; this migration makes the seed reproducible.
on conflict (canonical_value,canonical_type,normalized_alias)
do update set alias=excluded.alias, language=excluded.language, alias_type=excluded.alias_type, context=excluded.context, confidence=excluded.confidence, source=excluded.source, status=excluded.status, created_by=excluded.created_by, updated_at=now();
